/*
 * Накопитель на конденсаторе: заряд бустом, контроль АЦП, разряд по кнопке.
 * Плата: Arduino Uno / Nano (ATmega328)
 *
 * D7 — затвор T1 (IRL530N) через 560 Ом — ключ заряда
 * D6 — затвор T2 (IRL2905) через 560 Ом — ключ разряда
 * D5 — кнопка «спуск» на GND (внутренняя подтяжка)
 * D4 — светодиод «готовность» через 330 Ом
 * A0 — делитель R4 100k / R5 4,7k с плюса C2 (коэффициент 22,3)
 */

// ---------- НАСТРОЙКИ (править здесь) ----------
const float CHARGE_VOLTAGE   = 50.0;   // до скольки вольт заряжаем C2
const float VOLT_DIVIDER     = 22.30;  // (R4+R5)/R5 = 102.7/4.7
const float LED_BRIGHT_HYST  = 1.0;    // гистерезис, вольты на банке
const unsigned long TIMEOUT_MS = 30000; // таймаут заряда, мс (30 с)
const unsigned long DISCHARGE_MS = 100; // длительность импульса разряда, мс
const unsigned long LED_BLINK_FAST = 100; // период мигания при аварии, мс

// ---------- ПИНЫ ----------
const uint8_t PIN_CHARGE   = 7;  // T1
const uint8_t PIN_DISCHARGE= 6;  // T2
const uint8_t PIN_BUTTON   = 5;  // спуск
const uint8_t PIN_LED      = 4;  // готовность
const uint8_t PIN_VOLTAGE  = A0; // напряжение банки

// ---------- Состояния ----------
enum State : uint8_t { CHARGING, READY, FIRED, ERROR };
State state = CHARGING;

unsigned long chargeStart = 0;
unsigned long dischargeStart = 0;
unsigned long blinkTimer = 0;

// Порог в единицах АЦП (10 бит, опора 5 В)
const int ADC_THRESHOLD = (int)(CHARGE_VOLTAGE / VOLT_DIVIDER / 5.0 * 1024.0);
// Гистерезис тоже в отсчётах
const int ADC_HYST = (int)(LED_BRIGHT_HYST / VOLT_DIVIDER / 5.0 * 1024.0);

float batteryVoltage() {
  // Читаем 8 выборок и усредняем — убираем шум от импульсного заряда
  long sum = 0;
  for (uint8_t i = 0; i < 8; i++) sum += analogRead(PIN_VOLTAGE);
  float adc = sum / 8.0;
  return adc / 1024.0 * 5.0 * VOLT_DIVIDER;
}

void startCharge() {
  digitalWrite(PIN_CHARGE, HIGH);
  chargeStart = millis();
  state = CHARGING;
}

void stopCharge() {
  digitalWrite(PIN_CHARGE, LOW);
}

void setup() {
  pinMode(PIN_CHARGE, OUTPUT);
  pinMode(PIN_DISCHARGE, OUTPUT);
  pinMode(PIN_LED, OUTPUT);
  pinMode(PIN_BUTTON, INPUT_PULLUP);

  // Гарантируем, что силовые ключи ЗАКРЫТЫ до начала работы
  digitalWrite(PIN_CHARGE, LOW);
  digitalWrite(PIN_DISCHARGE, LOW);

  startCharge(); // после включения сразу начинаем заряжать
}

void loop() {
  float u = batteryVoltage();

  // ---------- Кнопка «спуск» ----------
  // Работает только в READY. Антидребезг простым ожиданием отпускания.
  if (state == READY && digitalRead(PIN_BUTTON) == LOW) {
    digitalWrite(PIN_LED, LOW);
    digitalWrite(PIN_DISCHARGE, HIGH);
    dischargeStart = millis();
    state = FIRED;
    while (digitalRead(PIN_BUTTON) == LOW) { delay(10); } // ждём отпускания
  }

  // ---------- Импульс разряда ----------
  if (state == FIRED) {
    if (millis() - dischargeStart >= DISCHARGE_MS) {
      digitalWrite(PIN_DISCHARGE, LOW);
      startCharge(); // зарядили -> выстрелили -> снова заряжаем
    }
    return;
  }

  // ---------- Цикл заряда ----------
  if (state == CHARGING) {
    // Авария: слишком долго заряжаемся — что-то не так
    if (millis() - chargeStart > TIMEOUT_MS) {
      stopCharge();
      state = ERROR;
    }
    // Достали порог с учётом гистерезиса
    if (u >= CHARGE_VOLTAGE) {
      stopCharge();
      digitalWrite(PIN_LED, HIGH); // «готовность»
      state = READY;
    }
  }

  // ---------- Аварийное состояние ----------
  if (state == ERROR) {
    // Мигаем светодиодом быстро: заряд не дошёл до порога за таймаут
    if (millis() - blinkTimer >= LED_BLINK_FAST) {
      blinkTimer = millis();
      digitalWrite(PIN_LED, !digitalRead(PIN_LED));
    }
    // Долгое нажатие кнопки (>2 с) — сброс ошибки и новая попытка
    if (digitalRead(PIN_BUTTON) == LOW) {
      unsigned long t0 = millis();
      while (digitalRead(PIN_BUTTON) == LOW && millis() - t0 < 2000) delay(10);
      if (digitalRead(PIN_BUTTON) == LOW) { // держали больше 2 с
        startCharge();
      }
    }
  }
}
